hooks.command:
#!/bin/bash
# Block creation of unnecessary documentation files
# 豁免：文档正典 / skills 与 agents 定义 / .auto 协议产物 / docs 与 tests 目录 / Claude memory 目录
input=$(cat)
file_path=$(printf '%s' "$input" | node -e "const d=require('fs').readFileSync(0,'utf8');const j=JSON.parse(d);process.stdout.write(j.tool_input?.file_path||'')")
p=$(echo "$file_path" | tr '\\\\' '/')

case "$p" in
  *.md|*.txt) ;;
  *) :; exit 0 ;;
esac

case "$p" in
  */README*|README*|*/CLAUDE*|CLAUDE*|*/AGENTS*|AGENTS*|*/CONTRIBUTING*|CONTRIBUTING*|*/CHANGELOG*|CHANGELOG*|*/REPO_MAP*|REPO_MAP*|*/LICENSE*|LICENSE*) :; exit 0 ;;
  */skills/*|skills/*|*/agents/*|agents/*|*/commands/*|commands/*|*/rules/*|rules/*) :; exit 0 ;;
  */.auto/*|.auto/*|*/docs/*|docs/*|*/tests/*|tests/*|*/.github/*|.github/*|*/memory/*|memory/*) :; exit 0 ;;
esac

echo "[Hook] BLOCKED: Unnecessary documentation file creation" >&2
echo "[Hook] File: $file_path" >&2
echo "[Hook] Use README.md for documentation instead" >&2
exit 2
